package com.paydock.feature.card.domain.model.ui

import org.json.JSONObject

/**
 * Represents the details of a payment token generated by the payment processing system.
 *
 * This data class contains the token string and its associated type, along with optional
 * contact information linked to the payment source.
 *
 * @property token The payment token string, which can be null if the token generation fails.
 * @property type The type of payment source associated with the token (e.g., "credit_card", "paypal").
 * @property email The email address associated with the payment token, if provided.
 */
data class TokenDetails(
    val token: String?,
    val type: String,
    val email: String? = null,
    val billingAddress: JSONObject? = null,
    val shippingAddress: JSONObject? = null
)
